// ❌ OLD: Required installing ts-jest, babel-jest, and maintaining config files.
module.exports = {
  preset: 'ts-jest',
  testEnvironment: 'node',
  transform: {
    '^.+\.tsx?$': 'ts-jest'
  }
};

import { describe, it, expect, mock } from 'bun:test';

// ✅ NEW: Native TypeScript execution with zero extra npm packages
describe('Math utilities', () => {
  it('adds numbers correctly', () => {
    expect(2 + 2).toBe(4);
  });

  it('supports function spies and mocking', () => {
    const fn = mock((x: number) => x * 2);
    fn(5);
    expect(fn).toHaveBeenCalledTimes(1);
    expect(fn).toHaveReturnedWith(10);
  });
});
